{
 "app_name": "phone",
 "api_name": "show_voice_message_window",
 "path": "/phone/messages/voice/window",
 "method": "GET",
 "description": "Show voice messages with a contact around a given date and time.",
 "parameters": [
  {
   "name": "phone_number",
   "type": "string",
   "required": true,
   "description": "The phone number of the contact to show messages with.",
   "default": null,
   "constraints": []
  },
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from phone app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "min_datetime",
   "type": "string",
   "required": false,
   "description": "The minimum datetime to show messages on or after in YYYY-MM-DD|HH:MM:SS format.",
   "default": "1500-01-01|00:00:00",
   "constraints": []
  },
  {
   "name": "max_datetime",
   "type": "string",
   "required": false,
   "description": "The maximum datetime to show messages on or before in YYYY-MM-DD|HH:MM:SS format.",
   "default": "3000-01-01|00:00:00",
   "constraints": []
  },
  {
   "name": "pagination_order",
   "type": "string",
   "required": false,
   "description": "If set to ascending, as page_index increases, the results will have newer messages. If set to descending, as page_index increases, the results will have older messages. The messages within each page will always be oldest to newest.",
   "default": "descending",
   "constraints": [
    "value in ['ascending', 'descending']"
   ]
  },
  {
   "name": "page_index",
   "type": "integer",
   "required": false,
   "description": "The index of the page to return.",
   "default": 0,
   "constraints": [
    "value >= 0"
   ]
  },
  {
   "name": "page_limit",
   "type": "integer",
   "required": false,
   "description": "The maximum number of results to return per page.",
   "default": 5,
   "constraints": [
    "value >= 1, <= 20"
   ]
  }
 ],
 "response_schemas": {
  "success": [
   {
    "voice_message_id": 1,
    "sender": {
     "contact_id": 1,
     "name": "string",
     "phone_number": "string"
    },
    "receiver": {
     "contact_id": 1,
     "name": "string",
     "phone_number": "string"
    },
    "message": "string",
    "sent_at": "2019-01-01T00:00:00"
   }
  ],
  "failure": {
   "message": "string"
  }
 }
}

